/* English dictionary for lazysheepcapital/candlesticks/ (zh source stays verbatim in index.html + patterns.js).
 *
 * Pattern text: CANDLE_EN (below) holds English s/rec/psy/use per pattern id. On DOMContentLoaded the
 * zh→en dictionary is built from window.CANDLE_PATTERNS (zh name → en name, zh text → CANDLE_EN text),
 * so every rendered card / table row / modal is translated by i18n.js's DOM walker + MutationObserver.
 * index.html also folds CANDLE_EN into the search haystack, so English keywords match in both languages.
 */
I18N.html({
  '蜡烛图<span class="grad">形态大全</span>': 'Candlestick <span class="grad">Patterns</span>',
  '<b>实体</b>：开盘价和收盘价之间的部分': '<b>Real body</b>: the part between the open and the close',
  '<b>阳线</b>：收盘 &gt; 开盘（涨）　<b>阴线</b>：收盘 &lt; 开盘（跌）':
    '<b>Up candle</b>: close &gt; open (rise) &nbsp; <b>Down candle</b>: close &lt; open (fall)',
  '<b>上影线</b>：实体上方到最高价的细线': '<b>Upper shadow</b>: the thin line from the body up to the high',
  '<b>下影线</b>：实体下方到最低价的细线': '<b>Lower shadow</b>: the thin line from the body down to the low',
  '<b>窗口</b>：两根K线之间价格完全没有重叠的空白（缺口）':
    '<b>Window</b>: an empty space between two candles whose price ranges don\'t overlap at all (a gap)'
});

