I18N.patterns([
  [/^以 Steve Nison《日本蜡烛图技术》为主线，补充 Bulkowski、Morris 等人整理的统计形态，共 (\d+) 种K线形态 \+ (\d+) 项趋势与技术指标。每个形态都配有统一风格的示意图，并按「实用度」排名：越靠前越常见、越可靠、越值得先学。$/,
    function (m, a, b) { return "Built around Steve Nison's Japanese Candlestick Charting Techniques, plus statistical patterns compiled by Bulkowski, Morris and others: " + a + " candlestick patterns + " + b + " trend and technical tools. Every pattern has a diagram in the same style and is ranked by usefulness: the higher it ranks, the more common, reliable and worth learning first."; }],
  [/^以 Steve Nison《日本蜡烛图技术》为主线/, "Built around Steve Nison's Japanese Candlestick Charting Techniques, plus statistical patterns compiled by Bulkowski, Morris and others. Every pattern has a diagram in the same style and is ranked by usefulness: the higher it ranks, the more common, reliable and worth learning first."],
  [/^(\d+) 根K线$/, function (m, n) { return n + (n === "1" ? " candle" : " candles"); }],
  [/^(\d+) 种$/, function (m, n) { return n + " patterns"; }],
  [/^K线必须放在趋势里看 · (\d+) 项$/, function (m, n) { return "Candles must be read in the context of the trend · " + n + " items"; }],
  [/^(.+?)\s*·\s*实用度排名 (\S+)$/, function (m, en, r) { return "Usefulness rank " + r; }],
  [/^(.+)示意图$/, function (m, name) { return I18N.tr(name) + " diagram"; }],
  [/^← (.+)$/, function (m, name) { return "← " + I18N.tr(name); }],
  [/^(.+) →$/, function (m, name) { return I18N.tr(name) + " →"; }]
]);

document.addEventListener("DOMContentLoaded", function () {
  var P = window.CANDLE_PATTERNS, E = window.CANDLE_EN, d = {};
  if (!P) return;
  P.forEach(function (p) {
    d[p.zh] = p.en;
    var e = E[p.id] || {};
    ["s", "rec", "psy", "use"].forEach(function (f) { if (p[f] && e[f]) d[p[f]] = e[f]; });
  });
  I18N.add(d);
  I18N.retranslate();
});

window.CANDLE_EN ={
  "hammer": {"s": "In a downtrend, a candle with a long \"tail\" hanging below, like a hammer \"hammering out\" a bottom.", "rec": "Appears in a downtrend; small real body at the top of the range; lower shadow at least 2× the body; little or no upper shadow. Body color doesn't matter, though an up candle is slightly stronger.", "psy": "Bears drove prices sharply lower after the open, but bulls pulled them back near the open by the close: the bears have lost control.", "use": "Best to wait for confirmation: a next-day close above the hammer's body makes the signal more reliable. The hammer's low can serve as the stop-loss. The longer the lower shadow and the closer to key support, the stronger the signal."},
  "hanging-man": {"s": "Looks exactly like a hammer, but appears high up after a rally, like a hanging man. A danger sign.", "rec": "Same shape as the Hammer, but appears at a high after an uptrend. Lower shadow ≥ 2× the body, little or no upper shadow.", "psy": "A clear sell-off happened intraday, showing some holders cashing out at the highs; even though the close recovered, the bulls' footing has weakened.", "use": "Needs confirmation: the next day opens below the hanging man's body, or closes as a down candle below the body. A black body is more bearish than a white one. On its own, only moderately reliable."},
  "inverted-hammer": {"s": "In a downtrend, a candle with a long \"antenna\" on top and a small body at the bottom.", "rec": "Appears in a downtrend; small body at the bottom of the range; long upper shadow ≥ 2× the body; little or no lower shadow. Same shape as the Shooting Star.", "psy": "Bulls tried to rally and were pushed back, but bears could no longer force a lower close. A \"tentative\" bottom signal.", "use": "Needs stricter confirmation than the Hammer: ideally the next day gaps up and closes as an up candle. Without confirmation, don't buy the bottom on an inverted hammer alone."},
  "shooting-star": {"s": "In an uptrend, a long \"antenna\" on top: a spike higher that gets knocked back, like a shooting star.", "rec": "Appears in an uptrend; small body at the bottom of the range, long upper shadow ≥ 2× the body, little or no lower shadow. Ideally there is a gap between its body and the prior candle.", "psy": "Bulls kept pushing higher after the open but hit heavy selling up top; the close is back near the low: the rally failed.", "use": "Confirmed by a next-day close below the star's body. The shooting star's high is a natural resistance/stop-loss level. More reliable at a prior high or resistance."},
  "gravestone-doji": {"s": "Open, close and low are all at the same level, with only a long upper shadow, like a gravestone.", "rec": "Open = close = low (or very close), with only a long upper shadow, shaped like \"⊥\".", "psy": "Bulls pushed prices high, but all gains were erased and the day closed at its low. At a high this is a very strong bearish signal; the name itself means \"burying the bulls\".", "use": "Most effective at the top of an uptrend; less meaningful in a downtrend. Wait for a following down candle to confirm."},
  "dragonfly-doji": {"s": "Open, close and high are all at the same level, with only a long lower shadow, like a dragonfly.", "rec": "Open = close = high, with only a long lower shadow, shaped like \"T\". Can be seen as an extreme Hammer.", "psy": "Bears pushed prices far lower intraday, but the close recovered everything, showing strong buying at lower levels.", "use": "Most meaningful at the bottom of a downtrend or at key support; confirm with an up candle the next day. At a high it acts like a Hanging Man and is bearish instead."},
  "long-legged-doji": {"s": "Open ≈ close with long shadows on both sides: a fierce bull-bear fight that ends in a draw.", "rec": "Open ≈ close, with long upper and lower shadows.", "psy": "Bulls and bears fought hard all day and ended in a draw: the market has lost all sense of direction.", "use": "After a long rally it warns the trend may be topping; inside a sideways range it means little. Location is what matters."},
  "rickshaw-man": {"s": "A Long-Legged Doji with the cross exactly in the middle.", "rec": "A type of Long-Legged Doji: the body (cross) sits exactly in the middle of the candle's range.", "psy": "Same as the Long-Legged Doji: supply and demand are perfectly balanced and the market is undecided.", "use": "The original book treats it as a special Long-Legged Doji. At a high or low it hints the trend may change."},
  "doji": {"s": "Open ≈ close, so the body is just a horizontal line: the market is undecided.", "rec": "Open and close are equal or nearly equal, so the body is a horizontal line. \"Nearly equal\" should be judged relative to recent body sizes.", "psy": "The market is hesitating at a turning point. Nison notes a doji warns more in an uptrend than in a downtrend: rallies need steady buying, while declines can fall under their own weight.", "use": "A doji is not a trade signal by itself, but a \"pay attention\" signal. After a long up candle or in overbought territory, tighten stops. If dojis appear frequently, a single one means little."},
  "northern-doji": {"s": "A doji during an uptrend: the rally may be stalling.", "rec": "A doji appearing in an uptrend (price is \"north\", i.e. high).", "psy": "Hesitation in an uptrend shows buying momentum is fading. Nison considers dojis at highs fairly reliable bearish signals.", "use": "A following down candle closing below the doji confirms a top; it can also prompt trimming positions or tightening stops. (Name from Bulkowski; the view that dojis at highs matter more is from Nison.)"},
  "southern-doji": {"s": "A doji during a downtrend: the decline may slow, but the signal is weak.", "rec": "A doji appearing in a downtrend (at lows).", "psy": "Selling pressure is temporarily balanced. But a doji in a downtrend matters less than in an uptrend: prices can \"free-fall\" without steady selling.", "use": "Needs a following up candle to confirm; on its own it's often just a brief pause in the decline. (Name from Bulkowski.)"},
  "spinning-top": {"s": "Small body with shadows on both sides: bulls and bears are about even.", "rec": "Small real body (up or down), moderate upper and lower shadows, usually longer than the body.", "psy": "Bulls and bears are nearing balance; the existing trend is losing momentum.", "use": "After a long up or down candle, it hints the trend is running out of steam. It is also a building block of multi-candle patterns such as stars and harami."},
  "high-wave": {"s": "Small body with very long shadows on both sides: market sentiment is chaotic.", "rec": "Small real body, but very long upper and lower shadows.", "psy": "Sentiment is swinging wildly and direction is completely lost. Several high-wave candles in a row often precede a trend change.", "use": "Stay alert when it appears late in a rally or decline; act on a confirming candle."},
  "takuri": {"s": "A stronger Hammer, with a lower shadow at least 3× the body.", "rec": "A stronger Hammer: lower shadow at least 3× the body, little or no upper shadow. The Japanese \"takuri\" means \"to gauge the water's depth\".", "psy": "Bears pushed prices to the \"bottom of the water\", only to be pulled all the way back: very strong buying underneath.", "use": "Same as the Hammer: enter after next-day confirmation, with a stop-loss below the low."},
  "bull-belt-hold": {"s": "In a downtrend, the open is the low of the day, and price climbs all the way to the close.", "rec": "In a downtrend, the open is the day's low (no lower shadow), then price rises steadily into a long up candle with little or no lower shadow.", "psy": "After a low open, bulls took over immediately and never gave bears a chance. The Japanese \"yorikiri\" is a sumo term: grabbing the opponent's belt and pushing him out of the ring.", "use": "The longer the body, the more it matters. If a later candle closes below the belt-hold's low, the signal is void."},
  "bear-belt-hold": {"s": "In an uptrend, the open is the high of the day, and price falls all the way to the close.", "rec": "In an uptrend, the open is the day's high (no upper shadow), then price falls steadily into a long down candle.", "psy": "After a high open, bears took control at once, with selling all day long.", "use": "If a later candle closes back above the belt-hold's high, the signal is void. More meaningful after a long rally."},
  "white-marubozu": {"s": "A big up candle with no shadows: bulls in full control all day.", "rec": "A long up candle with no upper or lower shadow: open = low, close = high. \"Marubozu\" means \"shaved head\".", "psy": "Bulls controlled the session from open to close: strong bullish force.", "use": "When it breaks out of a sideways range, it's strong evidence of a valid breakout; after a long rally it may be an emotional \"final sprint\". Its midpoint often acts as support."},
  "black-marubozu": {"s": "A big down candle with no shadows: bears in full control all day.", "rec": "A long down candle with no upper or lower shadow: open = high, close = low.", "psy": "Bears controlled the session from open to close: strong bearish force.", "use": "When it breaks support, the breakdown is likely valid; after a long decline it may mark the tail end of panic selling."},
  "closing-marubozu-w": {"s": "A big up candle closing at the high, with only a lower shadow.", "rec": "A long up candle with close = high (no upper shadow), but with a lower shadow.", "psy": "Buying was still strong into the close; bulls pushed price to the day's high before the bell.", "use": "Common as a continuation in uptrends; slightly weaker than a White Marubozu."},
  "closing-marubozu-b": {"s": "A big down candle closing at the low, with only an upper shadow.", "rec": "A long down candle with close = low (no lower shadow), but with an upper shadow.", "psy": "Selling was still heavy into the close; bears pushed price to the day's low before the bell.", "use": "Common as a continuation in downtrends; near support, watch for a breakdown."},
  "opening-marubozu-w": {"s": "A big up candle opening at the low, with only an upper shadow.", "rec": "A long up candle with open = low (no lower shadow), but with an upper shadow.", "psy": "Price rose steadily from the open but slipped a little late in the session.", "use": "Weaker than a Closing White Marubozu (profit-taking near the close). Limited practical value."},
  "opening-marubozu-b": {"s": "A big down candle opening at the high, with only a lower shadow.", "rec": "A long down candle with open = high (no upper shadow), but with a lower shadow.", "psy": "Price fell steadily from the open but found some buying late in the session.", "use": "Weaker than a Closing Black Marubozu. Limited practical value."},
  "long-white": {"s": "An up candle with an unusually long body: bulls are strong.", "rec": "An up candle whose body is clearly longer than the recent average, with short shadows.", "psy": "Bulls have the upper hand. Nison stresses that when a long up candle breaks resistance, that resistance often turns into support.", "use": "A single long up candle is not a reversal signal, but it is part of patterns like Engulfing, Piercing Pattern and Morning Star, and is often used to confirm other patterns."},
  "long-black": {"s": "A down candle with an unusually long body: bears are strong.", "rec": "A down candle whose body is clearly longer than the recent average, with short shadows.", "psy": "Bears have the upper hand. When a long down candle breaks support, that support often turns into resistance.", "use": "Often the confirming candle for patterns such as Dark Cloud Cover, Evening Star and Bearish Engulfing."},
  "short-line": {"s": "A candle with a short body and short shadows: nobody wants to move.", "rec": "A candle with a short body and short shadows, with a range smaller than the recent average.", "psy": "Thin trading; neither bulls nor bears show much conviction.", "use": "No trading meaning on its own; several in a row show the market building energy before choosing a direction."},
  "long-upper-shadow": {"s": "An unusually long upper shadow: someone is selling up there.", "rec": "Very long upper shadow (usually ≥ 2/3 of the candle's range), body at the bottom, up or down candle.", "psy": "A long upper shadow shows supply at higher prices; bulls couldn't hold the highs. (Nison stresses shadows matter as much as bodies; naming it as a standalone pattern comes from Morris.)", "use": "Bearish near resistance or a prior high; related to the Shooting Star and Gravestone Doji."},
  "long-lower-shadow": {"s": "An unusually long lower shadow: someone is buying down there.", "rec": "Very long lower shadow (usually ≥ 2/3 of the candle's range), body at the top, up or down candle.", "psy": "There is demand at lower prices; bears couldn't hold the lows.", "use": "Bullish near support; related to the Hammer and Dragonfly Doji."},
  "bull-engulfing": {"s": "In a downtrend, a big up candle completely \"swallows\" the prior down candle.", "rec": "1) A clear prior downtrend; 2) the first candle is a (smaller) down candle; 3) the second is an up candle whose real body fully covers the first's real body (shadows don't count).", "psy": "Bears wanted to keep pushing lower, but bulls turned the tables and drove price above the prior day's open: the balance of power flipped in a single session.", "use": "Nison ranks it among the most important reversal patterns. The bigger the second candle, the higher the volume, and the more candles it engulfs, the stronger the signal. Place the stop-loss below the low of the two candles."},
  "bear-engulfing": {"s": "In an uptrend, a big down candle completely \"swallows\" the prior up candle.", "rec": "1) A clear prior uptrend; 2) the first candle is an up candle; 3) the second is a down candle whose real body fully covers the first's real body.", "psy": "Bulls opened higher but were overwhelmed by bears, closing below the prior day's open: everyone who bought the rally is now trapped.", "use": "One of the most widely used and reliable topping signals. The high of the two candles is resistance/stop-loss. Take it especially seriously after a long rally or near resistance."},
  "dark-cloud": {"s": "In an uptrend, a gap-up open that then falls below the midpoint of the prior up candle's body.", "rec": "1) Uptrend; 2) the first candle is a long up candle; 3) the second opens above the prior high, then closes as a down candle well below the 50% point of the first candle's body.", "psy": "In the morning prices were still making new highs, but by the close most of the prior day's gain was gone: a dark cloud has covered the sun.", "use": "The deeper the close into the up candle's body, the stronger the signal; if it fully engulfs it, it becomes a Bearish Engulfing (stronger). The second candle's high is resistance."},
  "piercing": {"s": "In a downtrend, a gap-down open that then rallies above the midpoint of the prior down candle's body.", "rec": "1) Downtrend; 2) the first candle is a long down candle; 3) the second opens below the prior low, then closes as an up candle above the 50% point of the down candle's body.", "psy": "In the morning prices were still making new lows, yet the close recovered most of the losses: the opposite of Dark Cloud Cover.", "use": "The close must exceed the midpoint of the down candle's body; otherwise it's only a Thrusting Line or In-Neck Line (bearish continuation patterns). Place the stop-loss below the second candle's low."},
  "bull-harami": {"s": "In a downtrend, a big down candle followed by a small candle \"tucked inside\" its body.", "rec": "1) Downtrend; 2) the first candle is a long down candle; 3) the second has a small real body (either color, an up candle is better) lying entirely within the first's body. The opposite of an Engulfing pattern.", "psy": "\"Harami\" is Japanese for \"pregnant\". A sudden narrowing of range after a long down candle shows downside momentum is braking.", "use": "A harami says the trend may stop, not necessarily that it reverses at once. Wait for a third up candle closing above the first down candle's open to confirm (i.e. Three Inside Up)."},
  "bear-harami": {"s": "In an uptrend, a big up candle followed by a small candle tucked inside its body.", "rec": "1) Uptrend; 2) the first candle is a long up candle; 3) the second has a small real body lying entirely within the first's body.", "psy": "The rally suddenly runs out of steam after a long up candle; bullish momentum is braking.", "use": "More a hint that the rally is pausing: consider trimming positions or tightening stops. A lower close on the third candle is a clearer top (i.e. Three Inside Down)."},
  "bull-harami-cross": {"s": "A harami whose second candle is a doji, a stronger reversal hint than a regular harami.", "rec": "Same as the Bullish Harami, but the second candle is a doji (open ≈ close).", "psy": "After a long down candle the market is completely undecided; the bears have lost their momentum.", "use": "Nison considers the harami cross an important reversal pattern, more significant than a regular harami. Still wait for an up candle the next day as confirmation."},
  "bear-harami-cross": {"s": "A doji contained within a big up candle; the rally may be topping.", "rec": "Same as the Bearish Harami, but the second candle is a doji.", "psy": "Sudden indecision after a long up candle. A rally needs sustained buying, and the doji shows the buying has dried up.", "use": "A strong warning when it appears at the end of a long uptrend. Consider trimming positions or tightening stops."},
  "tweezers-top": {"s": "Two (or more) adjacent candles with nearly identical highs, forming a flat top.", "rec": "In an uptrend, two or more candles have the same or nearly the same high (like the two tips of tweezers). They need not be adjacent, but adjacent is better.", "psy": "Price failed twice at the same level, showing a \"ceiling\" there.", "use": "A modest signal on its own; much more reliable if it also forms a Bearish Engulfing, Dark Cloud Cover or Bearish Harami, or if the second candle is a Shooting Star. The tweezers high is resistance."},
  "tweezers-bottom": {"s": "Two adjacent candles with nearly identical lows, forming a flat bottom.", "rec": "In a downtrend, two or more candles have the same or nearly the same low.", "psy": "Price was held up twice at the same level; there is a \"floor\" below.", "use": "More reliable when combined with a Bullish Engulfing, Piercing Pattern, harami or Hammer. The tweezers low is support and the stop-loss level."},
  "bull-counterattack": {"s": "In a downtrend, opens sharply lower but closes right back at the prior close.", "rec": "1) Downtrend; 2) a long down candle; 3) the second candle gaps sharply lower, then closes as a long up candle at or near the prior close.", "psy": "Bears held every advantage at the open, yet bulls won back all the lost ground within the day, fighting to a draw.", "use": "Weaker than the Piercing Pattern (it does not push into the down candle's body). Needs confirmation from the following candles."},
  "bear-counterattack": {"s": "In an uptrend, opens sharply higher but closes right back at the prior close.", "rec": "1) Uptrend; 2) a long up candle; 3) the second candle gaps sharply higher, then closes as a long down candle at the prior close.", "psy": "A big rally at the open, all given back by the close; the bulls' optimism is doused.", "use": "A weaker version of Dark Cloud Cover. The second candle's high is resistance."},
  "bull-separating": {"s": "A one-candle pullback in an uptrend; the next day opens at the same price and rallies.", "rec": "1) Uptrend; 2) the first candle is a down candle (against the trend); 3) the second, an up candle, opens at the first candle's open and rises from there.", "psy": "The pullback was a one-day blip; bulls immediately \"separate\" from it and resume the advance.", "use": "A continuation pattern: the uptrend is intact. Stronger if the second candle is a belt-hold."},
  "bear-separating": {"s": "A one-candle bounce in a downtrend; the next day opens at the same price and falls.", "rec": "1) Downtrend; 2) the first candle is an up candle (a counter-trend bounce); 3) the second, a down candle, opens at the first candle's open and falls from there.", "psy": "The bounce is cut off at once and bears regain control.", "use": "Continuation pattern: the downtrend continues; don't chase the bounce."},
  "on-neck": {"s": "A small bounce in a downtrend that only reaches the prior down candle's low. Too weak.", "rec": "1) Downtrend; 2) a long down candle; 3) the second opens lower and closes as a small up candle, only back near the prior candle's low.", "psy": "The bulls' counterattack doesn't even reach the down candle's body; it just \"sticks its neck\" up to the prior candle's bottom.", "use": "Bearish continuation: the decline resumes when price breaks below this small up candle's low. Don't mistake it for a Piercing Pattern."},
  "in-neck": {"s": "A small bounce in a downtrend that closes just barely inside the prior down candle's body.", "rec": "Like the On-Neck Line, but the up candle closes slightly above the down candle's close, just nicking the bottom of its body.", "psy": "The bounce is still very weak.", "use": "Bearish continuation. Order of strength: On-Neck Line < In-Neck Line < Thrusting Line < Piercing Pattern (only the last is a reversal)."},
  "thrusting": {"s": "A bounce in a downtrend that closes inside the down candle's body, but not past halfway.", "rec": "Like the In-Neck Line, but the up candle closes well into the down candle's body, yet still below its midpoint.", "psy": "Stronger than the In-Neck Line, but without clearing the midpoint the bulls haven't regained control.", "use": "Leans bearish in a downtrend; Nison says it can be read as bullish when it appears in a pullback within an uptrend. Two thrusting lines within a few days can also be bullish."},
  "bull-kicking": {"s": "A Black Marubozu followed by a gap up into a White Marubozu.", "rec": "The first candle is a Black Marubozu; the second gaps up (opens above the first's open) and closes as a White Marubozu, leaving a gap between them.", "psy": "Sentiment turns 180° in a single day, usually on major news.", "use": "Rare but powerful when it appears. The gap is support. Does not depend on the prior trend."},
  "bear-kicking": {"s": "A White Marubozu followed by a gap down into a Black Marubozu.", "rec": "The first candle is a White Marubozu; the second gaps down and closes as a Black Marubozu.", "psy": "A sharp reversal in sentiment, most likely on bad news.", "use": "Rare but strong. The gap becomes resistance."},
  "bull-doji-star": {"s": "A doji that gaps down after a long down candle; the decline may be stalling.", "rec": "1) Downtrend; 2) a long down candle; 3) a doji that gaps down (a gap between its body and the prior body).", "psy": "After pressing lower, the bears lose steam and the market turns indecisive.", "use": "The first two candles of a Morning Doji Star. If the next day is a long up candle closing well into the first candle's body, the Morning Doji Star is complete."},
  "bear-doji-star": {"s": "A doji that gaps up after a long up candle; the rally may be topping.", "rec": "1) Uptrend; 2) a long up candle; 3) a doji that gaps up.", "psy": "A gap up with no follow-through buying; bulls and bears are deadlocked.", "use": "The first two candles of an Evening Doji Star. Nison advises protecting profits as soon as a doji star appears at a high."},
  "homing-pigeon": {"s": "Like a Bullish Harami, but both candles are down candles.", "rec": "1) Downtrend; 2) a long down candle; 3) a smaller down candle whose body lies entirely within the first body.", "psy": "Still falling, but by much less; selling pressure is fading.", "use": "Statistically mediocre and unreliable alone; needs a following up candle for confirmation."},
  "above-stomach": {"s": "In a downtrend, an up candle that opens and closes above the prior down candle's midpoint.", "rec": "1) Downtrend; 2) a down candle; 3) an up candle that opens and closes above the midpoint of the first candle's body.", "psy": "Bulls are in charge from the open; bears never get a chance.", "use": "A pattern catalogued by Bulkowski. Unlike the Piercing Pattern, it needs no lower open: the second candle sits above the down candle's midpoint from the open."},
  "below-stomach": {"s": "In an uptrend, a down candle that opens and closes below the prior up candle's midpoint.", "rec": "1) Uptrend; 2) an up candle; 3) a down candle that opens and closes below the midpoint of the first candle's body.", "psy": "More than half of the bulls' gains are wiped out at the next open.", "use": "A pattern catalogued by Bulkowski. Unlike Dark Cloud Cover, it needs no higher open: the second candle sits below the up candle's midpoint from the open."},
  "matching-low": {"s": "Two down candles close at the same price; that may be the bottom.", "rec": "1) Downtrend; 2) two down candles; 3) the same or nearly the same close.", "psy": "Bears pushed price to the same close twice but couldn't go lower, creating short-term support.", "use": "Similar to a Tweezers Bottom (closes only). Bulkowski found it acts more often as a continuation than a reversal, so be cautious."},
  "last-engulfing-top": {"s": "A \"Bullish Engulfing\" at the end of an uptrend that often marks the top instead.", "rec": "1) Uptrend; 2) a down candle; 3) an up candle fully engulfs it (it looks like a Bullish Engulfing, but at a high).", "psy": "The last burst of chasing at the highs; buying is exhausted.", "use": "Needs confirmation: the next candle closes below the engulfing up candle's close."},
  "last-engulfing-bottom": {"s": "A \"Bearish Engulfing\" at the end of a downtrend that often marks the bottom instead.", "rec": "1) Downtrend; 2) an up candle; 3) a down candle fully engulfs it (it looks like a Bearish Engulfing, but at a low).", "psy": "The final wave of panic selling.", "use": "Needs confirmation: the next candle closes above the engulfing down candle's close."},
  "rising-window": {"s": "Today's low is above yesterday's high, leaving an empty \"window (gap)\" between them.", "rec": "In a rally, the second candle's low is above the first candle's high, leaving a price void (a gap in Western terms).", "psy": "Buyers are so eager they skip a range of prices. The Japanese say \"the market returns to the window,\" but the window should act as support.", "use": "One of Nison's most valued continuation signals: the window (gap) is support. A pullback that holds the window = stay bullish; a close below the whole window = the rally has failed."},
  "falling-window": {"s": "Today's high is below yesterday's low, leaving an empty \"window (gap)\" between them.", "rec": "In a decline, the second candle's high is below the first candle's low.", "psy": "Sellers rush for the exit, skipping a range of prices.", "use": "The window (gap) is resistance. A bounce that stalls at the window = stay bearish; a close above the whole window = the decline has failed."},
  "gap-up-doji": {"s": "A doji that gaps up in an uptrend; the rally got hasty and is hesitating.", "rec": "In an uptrend, price gaps up and the second candle is a doji.", "psy": "The gap shows optimism, but the doji shows hesitation.", "use": "Of limited meaning alone; watch the direction of the following candles."},
  "gap-down-doji": {"s": "A doji that gaps down in a downtrend; the selloff got hasty and is hesitating.", "rec": "In a downtrend, price gaps down and the second candle is a doji.", "psy": "Hesitation amid panic.", "use": "More often a continuation of the decline; followed by an up candle it can signal the selling has stopped."},
  "bull-hikkake": {"s": "A fake breakdown lures in the bears, then price reverses higher.", "rec": "1) A harami (inside bar); 2) the next candle breaks below the inside bar's low (an apparent breakdown); 3) within a few candles price reverses and breaks above the inside bar's high.", "psy": "The false break shakes out stop-losses and short-chasers, then the real direction emerges.", "use": "Enter on a break above the inside bar's high, stop below the false-break low. A pattern codified by modern trader Dan Chesler, not from the original book."},
  "bear-hikkake": {"s": "A fake breakout lures in the bulls, then price reverses lower.", "rec": "1) An inside bar; 2) price then breaks above the inside bar's high; 3) within a few candles price reverses and breaks below the inside bar's low.", "psy": "The false breakout lures buyers chasing higher, then turns around.", "use": "Short or exit on a break below the inside bar's low, stop above the false-breakout high."},
  "morning-star": {"s": "Big down candle → small candle (the star) → big up candle. Night ends and the morning star rises.", "rec": "1) Downtrend; 2) a long down candle; 3) a small body that gaps down (the star, up or down); 4) a long up candle closing well into the first candle's body (ideally past halfway).", "psy": "Down candle: bears in control. Star: bears are out of steam, forces balance. Up candle: bulls take over. A step-by-step handover of power.", "use": "One of the most reliable bottom patterns. Stronger with gaps on both sides of the star, and with higher volume on the third candle. Place the stop below the star's low."},
  "evening-star": {"s": "Big up candle → small candle (the star) → big down candle. The sun sets and the evening star appears.", "rec": "1) Uptrend; 2) a long up candle; 3) a small-bodied star that gaps up; 4) a long down candle closing well into the first candle's body.", "psy": "Up candle: bulls strong. Star: the rally stalls. Down candle: bears take over.", "use": "One of the most reliable top patterns. The star's high is resistance and the stop level. The longer the third candle and the deeper it reaches, the stronger the signal."},
  "morning-doji-star": {"s": "A Morning Star whose middle candle is a doji, a stronger reversal signal.", "rec": "Same as the Morning Star, but the middle candle is a doji.", "psy": "A doji means total indecision, showing the bears' exhaustion more clearly than an ordinary star.", "use": "Stronger than a regular Morning Star, but rarer."},
  "evening-doji-star": {"s": "An Evening Star whose middle candle is a doji, a stronger topping signal.", "rec": "Same as the Evening Star, but the middle candle is a doji.", "psy": "Total indecision after a gap up at a high, then confirmed by a big down candle.", "use": "Nison stresses its importance at highs: even before the third candle appears, a doji star at a high is reason to turn defensive."},
  "bull-abandoned-baby": {"s": "The middle doji is \"isolated\" by gaps on both sides, like an abandoned baby.", "rec": "An extreme Morning Doji Star: the middle doji's shadows don't overlap the shadows of the candles on either side (gaps on both sides).", "psy": "The bears' final gap down is immediately \"abandoned\" by a bullish gap the other way.", "use": "Very rare, but highly reliable."},
  "bear-abandoned-baby": {"s": "A doji at a high with gaps on both sides, like an island.", "rec": "An extreme Evening Doji Star: the middle doji's shadows don't overlap those of the candles on either side. A form of what the West calls an \"island reversal.\"", "psy": "The last buyers at the top are \"stranded on the island.\"", "use": "Rare but highly reliable."},
  "three-white-soldiers": {"s": "Three steadily rising up candles in a row, like three soldiers marching in step.", "rec": "1) Appears after a low or a sideways range; 2) three consecutive up candles, each closing at a new high; 3) each opens within the prior real body; 4) each closes near its high (short upper shadows).", "psy": "Bulls advance steadily for three days; buying is persistent and healthy.", "use": "If the 2nd and 3rd real bodies shrink or their upper shadows lengthen, it becomes an Advance Block or Deliberation / Stalled pattern — a warning sign. After a big rally, watch for overbought conditions."},
  "three-black-crows": {"s": "Three falling down candles in a row at a high, like three crows on a branch — a bad omen.", "rec": "1) Uptrend or high price level; 2) three consecutive down candles, each closing at a new low; 3) each opens within the prior real body; 4) each closes near its low.", "psy": "Bears press for three straight days; holders at the top are running for the exit.", "use": "A reliable top signal. But if it appears after a large decline, the market may already be oversold, and chasing shorts is risky."},
  "identical-three-crows": {"s": "A stronger Three Black Crows: each down candle opens at the prior candle's close.", "rec": "Same as Three Black Crows, but the 2nd and 3rd candles open exactly at the prior close.", "psy": "No room for any bounce; the selling never lets up.", "use": "Rare; more bearish than regular Three Black Crows."},
  "advance-block": {"s": "Three up candles, each smaller with a longer upper shadow than the last — the rally is running out of steam.", "rec": "Like Three White Soldiers, but the 2nd and 3rd real bodies get progressively smaller and the upper shadows progressively longer.", "psy": "Bulls are still pushing, but each step meets heavier selling.", "use": "Not a signal to short right away, but a signal for longs to lighten up or protect profits."},
  "deliberation": {"s": "Two long up candles, then a sudden small one — the bulls start to \"deliberate\".", "rec": "The first two are long up candles; the third is a small up candle (Spinning Top), often gapping up or sitting at the top of the second.", "psy": "Upward momentum suddenly fades and the market pauses to weigh things up.", "use": "Like Advance Block, a time for longs to take profits, not a reason to short."},
  "upside-gap-two-crows": {"s": "After a long up candle, two down candles gap up; the second engulfs the first.", "rec": "1) Uptrend; 2) long up candle; 3) small down candle that gaps up; 4) a second down candle opens above the prior one's open and closes below its close (engulfing it), but still above the first up candle's close.", "psy": "Two gap-up opens both fail to hold; buying at the top is clearly weak.", "use": "Bearish signal is confirmed if a later candle closes below the first up candle's close."},
  "two-crows": {"s": "Like Upside-Gap Two Crows, but the second down candle falls into the long up candle's real body.", "rec": "1) Uptrend; 2) long up candle; 3) down candle that gaps up; 4) third down candle opens within the second's real body and closes deep inside the first up candle's body, filling the gap.", "psy": "More bearish than Upside-Gap Two Crows.", "use": "Similar to an Evening Star."},
  "three-inside-up": {"s": "Bullish Harami + a third up candle as confirmation.", "rec": "The first two candles form a Bullish Harami; the third up candle closes above the first down candle's open (or at least above its midpoint).", "psy": "The harami shows the decline has stalled; the third candle shows bulls have truly taken over.", "use": "Essentially \"harami + confirmation\" — far more reliable than a harami alone."},
  "three-inside-down": {"s": "Bearish Harami + a third down candle as confirmation.", "rec": "The first two candles form a Bearish Harami; the third down candle closes below the first up candle's open.", "psy": "The rally brakes first, then bears take over.", "use": "The confirmed version of a Bearish Harami; noticeably more reliable."},
  "three-outside-up": {"s": "Bullish Engulfing + a third up candle closing higher.", "rec": "The first two candles form a Bullish Engulfing; the third up candle closes higher.", "psy": "Bulls keep pushing after the engulfing, confirming the reversal.", "use": "The confirmed version of the engulfing pattern."},
  "three-outside-down": {"s": "Bearish Engulfing + a third down candle closing lower.", "rec": "The first two candles form a Bearish Engulfing; the third down candle closes lower.", "psy": "Bears keep pushing after the engulfing, confirming the top.", "use": "The confirmed version of a Bearish Engulfing."},
  "three-stars-south": {"s": "Three down candles, each smaller with a shorter lower shadow — selling pressure is fading.", "rec": "1) Downtrend; 2) long down candle with a long lower shadow; 3) smaller down candle with a low above the first's; 4) a tiny Black Marubozu within the second candle's range.", "psy": "The decline is losing momentum step by step.", "use": "Extremely rare; you will seldom see it in practice."},
  "unique-three-river": {"s": "Long down candle → hammer-like down candle at a new low → a small, lower up candle.", "rec": "1) Long down candle; 2) a down-candle harami that still makes a new low (long lower shadow); 3) small up candle closing below the second's close.", "psy": "The new low is quickly bought back; selling is exhausted.", "use": "Very rare; moderately reliable."},
  "stick-sandwich": {"s": "Down–up–down, with both down candles closing at the same price, like bread around a filling.", "rec": "1) Downtrend; 2) down candle; 3) up candle closing above the first's close; 4) down candle closing at the same price as the first.", "psy": "Two closes at the same price form support.", "use": "Can be seen as a variant of Matching Low; needs confirmation."},
  "ladder-bottom": {"s": "Successive down candles step down like stairs; a final gapping up candle ends the decline.", "rec": "1) Three successively lower down candles; 2) a fourth down candle with a clear upper shadow; 3) a fifth up candle opens above the fourth's real body (gap) and closes higher.", "psy": "The fourth candle's upper shadow is the bulls' first probe; the fifth completes the reversal.", "use": "Rare; moderately reliable."},
  "concealing-baby-swallow": {"s": "Four down candles; the last fully engulfs the one before it, shadows included — selling is exhausted.", "rec": "1) Two Black Marubozu; 2) a down candle that gaps down, with a long upper shadow reaching into the prior real body; 3) a fourth down candle fully engulfs the third, shadows included.", "psy": "The bears' last frenzied sell-off.", "use": "Extremely rare; a textbook pattern with limited practical value."},
  "bull-three-line-strike": {"s": "Three up candles rise, then one long down candle wipes out all three days' gains.", "rec": "1) Three White Soldiers in an uptrend; 2) a fourth down candle opens higher and closes below the first up candle's open.", "psy": "In theory, an uptrend continuing after profit-taking.", "use": "Note: Bulkowski's statistics show it actually acts more often as a bearish reversal — the opposite of its name. Trade the direction of the price breakout."},
  "bear-three-line-strike": {"s": "Three down candles fall, then one long up candle recovers all three days' losses.", "rec": "1) Three Black Crows in a downtrend; 2) a fourth up candle opens lower and closes above the first down candle's open.", "psy": "In theory, a downtrend continuing after short covering.", "use": "Like the bullish version, Bulkowski found it acts more often as a bullish reversal."},
  "two-black-gapping": {"s": "A gap down in a downtrend, followed by two down candles moving lower.", "rec": "1) Downtrend; 2) a gap down; 3) two consecutive down candles after the gap, the second closing lower.", "psy": "Selling continues after the gap; there is no strength to fill it.", "use": "A continuation signal for the downtrend; the gap acts as resistance."},
  "bull-tri-star": {"s": "Three dojis in a row, with the middle one lowest.", "rec": "1) Downtrend; 2) three consecutive dojis; 3) the middle doji gaps down and the third gaps up.", "psy": "Three straight days of total indecision; downside momentum is exhausted.", "use": "A rare but important pattern introduced by Nison. More meaningful on daily or higher timeframes."},
  "bear-tri-star": {"s": "Three dojis in a row, with the middle one highest.", "rec": "1) Uptrend; 2) three consecutive dojis; 3) the middle doji gaps up and the third gaps down.", "psy": "Sustained indecision at the top, forming a small \"island top\".", "use": "Rare; when it appears, protect long profits."},
  "rising-three": {"s": "Long up candle → three small down candles rest within its range → another long up candle makes a new high.", "rec": "1) Uptrend; 2) long up candle; 3) 2–4 small candles (usually down) pull back slightly, all within the first candle's high-low range; 4) a final long up candle closes at a new high.", "psy": "A \"rest\" in an uptrend. The small pullback is weak and doesn't break the first candle's low; bulls then push again.", "use": "A classic bullish continuation pattern. It fails if the small candles break below the first candle's low."},
  "falling-three": {"s": "Long down candle → three small up candles bounce within its range → another long down candle makes a new low.", "rec": "1) Downtrend; 2) long down candle; 3) 2–4 small up candles bounce, all within the first candle's range; 4) a final long down candle closes at a new low.", "psy": "A \"breather\" in a downtrend; the bounce is weak and bears push again.", "use": "A classic bearish continuation. If the bounce can't get above the first candle's high, don't try to catch the bottom."},
  "mat-hold": {"s": "A Rising Three Methods variant: after a long up candle, a gap up, a small pullback, then the rally resumes.", "rec": "1) Long up candle; 2) small down candle that gaps up; 3) two more small candles drift lower but stay above roughly the first candle's close; 4) a long up candle makes a new high.", "psy": "The pullback is shallower than in Rising Three Methods; bulls are stronger.", "use": "Mentioned in Nison's book; Bulkowski's statistics show good continuation but it is rare."},
  "upside-tasuki": {"s": "After a gap up, a down candle pulls back but doesn't fill the gap — the rally continues.", "rec": "1) Uptrend; 2) up candle that gaps up; 3) a down candle opens within the up candle's real body and closes inside the gap, without fully filling it.", "psy": "A tasuki is a sash used to tie back kimono sleeves. The pullback fails to close the window (gap), showing the window's support holds.", "use": "The pattern fails if the gap is completely filled."},
  "downside-tasuki": {"s": "After a gap down, an up candle bounces but doesn't fill the gap — the decline continues.", "rec": "1) Downtrend; 2) down candle that gaps down; 3) an up candle opens within the down candle's real body and closes inside the gap without fully filling it.", "psy": "The bounce fails to close the falling window (gap); bears remain in control.", "use": "The pattern fails if the gap is completely filled."},
  "upside-gap-side-by-side": {"s": "After a gap up, two up candles of similar size and similar opens stand side by side.", "rec": "1) A gap up during a rally; 2) two up candles after the gap, similar in size with similar opens (side by side).", "psy": "Bulls hold above the window (gap) for two days; the gap's support holds.", "use": "A bullish continuation signal; the window acts as support."},
  "downside-gap-side-by-side": {"s": "After a gap down, two side-by-side up candles appear but the bounce fails to fill the gap — the decline continues.", "rec": "1) A gap down during a decline; 2) two side-by-side up candles after the gap that don't fill it.", "psy": "The up candles may be just short covering, not real buying.", "use": "Nison notes this pattern is rare and its up candles can mislead. The falling window (gap) still acts as resistance."},
  "upside-gap-three": {"s": "After two up candles with a gap between them, a down candle fills the gap — still counted as a bullish continuation.", "rec": "1) In an uptrend, a gap between two up candles; 2) a third down candle opens within the second's real body and closes within the first's, filling the gap.", "psy": "After the gap is filled, bulls may push again.", "use": "Be careful: once the gap is filled, the window (gap) no longer provides support."},
  "downside-gap-three": {"s": "After two down candles with a gap between them, an up candle fills the gap — still counted as a bearish continuation.", "rec": "1) In a downtrend, a gap between two down candles; 2) a third up candle closes within the first's real body, filling the gap.", "psy": "Short covering; the decline may continue.", "use": "Only moderately reliable."},
  "bull-breakaway": {"s": "A gap down, a few more days of grinding lower, then a long up candle rallies back into the gap.", "rec": "1) Long down candle; 2) down candle that gaps down; 3) two more small candles continue lower; 4) a long up candle closes inside the gap between the first and second candles.", "psy": "An accelerating decline suddenly reverses; bears run out of follow-through.", "use": "Fairly rare."},
  "bear-breakaway": {"s": "A gap up, a few more days of grinding higher, then a long down candle falls back into the gap.", "rec": "1) Long up candle; 2) up candle that gaps up; 3) two more small candles continue higher; 4) a long down candle closes inside the gap.", "psy": "An accelerating rally suddenly reverses.", "use": "Fairly rare."},
  "tower-top": {"s": "A long up candle (left tower) → several small candles → a long down candle (right tower).", "rec": "1) A long up candle in an uptrend; 2) several small candles move sideways at the high; 3) a long down candle drops. The long candles on each side look like two towers.", "psy": "The bulls' surge turns into hesitation and is finally replaced by a bearish surge.", "use": "Similar to an Evening Star but longer. The longer the small candles move sideways, the more lasting the reversal is likely to be."},
  "tower-bottom": {"s": "A long down candle → several small candles → a long up candle, like two inverted towers.", "rec": "1) A long down candle in a downtrend; 2) several small candles moving sideways at the lows; 3) a long up candle rallies.", "psy": "The bears' assault fades into hesitation, then the bulls charge.", "use": "Similar to the Morning Star but unfolds over a longer period."},
  "dumpling-top": {"s": "A string of small candles traces a rounded top, confirmed by a final gap down.", "rec": "1) After a rally, small-bodied candles form a convex arc; 2) a falling window (gap down) then confirms it.", "psy": "The rally quietly loses momentum; the final gap signals it is over.", "use": "Same as the Western rounding top. Wait for the falling window to confirm."},
  "fry-pan-bottom": {"s": "A string of small candles traces a rounded bottom (like a pan), confirmed by a final gap up.", "rec": "1) After a decline, small-bodied candles form a concave arc; 2) a rising window (gap up) follows.", "psy": "Selling pressure slowly fades, buyers quietly step in, and a final gap confirms it.", "use": "Same as the Western rounding bottom. The rising window acts as support."},
  "high-price-gapping": {"s": "After a big rally, price moves sideways near the highs for a few days, then gaps up and breaks out.", "rec": "1) After a sharp rally; 2) a cluster of small candles consolidates near the highs (without pulling back); 3) a gap up breaks above the consolidation.", "psy": "Consolidating at the highs without a pullback shows strong bulls; the gap breakout announces a new leg up.", "use": "The window (gap) acts as support."},
  "low-price-gapping": {"s": "After a big decline, price moves sideways near the lows for a few days, then gaps down and breaks lower.", "rec": "1) After a sharp decline; 2) a cluster of small candles consolidates near the lows; 3) a gap down breaks below the consolidation.", "psy": "The consolidation is a false bottom; the gap down shows bears are still in control.", "use": "The falling window (gap) acts as resistance."},
  "three-gaps-up": {"s": "Three consecutive gaps up — the rally is too steep and likely to pull back.", "rec": "Three consecutive rising windows (gaps) in an uptrend.", "psy": "A Japanese saying: \"After three gaps, sell.\" Buying power is exhausted, akin to the Western exhaustion gap.", "use": "Reduce or take profits after the third window; don't chase."},
  "three-gaps-down": {"s": "Three consecutive gaps down — the decline is too steep and may bounce from oversold.", "rec": "Three consecutive falling windows (gaps) in a downtrend.", "psy": "Panic selling is overdone; shorts should cover.", "use": "A signal to cover shorts, not necessarily to go long."},
  "new-price-lines": {"s": "Eight to ten new highs in a row — the rally is stretched; time to take profits.", "rec": "8–10 consecutive candles closing at new highs (not all need to be up candles).", "psy": "Japanese traders consider the market overbought after 8–10 consecutive new highs; once the count is reached, it's time to bank profits.", "use": "A candlestick version of an overbought indicator. At 10 new highs, reduce positions or tighten stops; likewise, 8–10 consecutive new lows in a decline suggest covering shorts."},
  "three-buddha-top": {"s": "Three peaks with the middle one highest — like a temple's three Buddha statues, a large one flanked by two smaller ones.", "rec": "1) After a rally, three peaks form, the middle (head) highest and the sides (shoulders) lower; 2) the two troughs connect to form the neckline; 3) a close below the neckline confirms.", "psy": "The third peak (right shoulder) fails to make a new high, showing the bulls are exhausted.", "use": "The Japanese Three Buddha is the exact counterpart of the Western head and shoulders top, one of the most reliable top patterns. After the neckline breaks, price often pulls back to it, and the neckline turns from support into resistance. Target ≈ the distance from head to neckline."},
  "inverse-three-buddha": {"s": "Three troughs with the middle one lowest — the Three Buddha Top turned upside down.", "rec": "1) After a decline, three troughs form, the middle one lowest; 2) the two peaks connect to form the neckline; 3) a close above the neckline confirms.", "psy": "The right shoulder fails to make a new low, showing the bears are exhausted.", "use": "Equivalent to the Western inverse head and shoulders. After the breakout, the neckline becomes support."},
  "three-mountains": {"s": "Three failed attempts to break the same high — like three mountains of equal height.", "rec": "1) Price rallies three times to roughly the same high; 2) it falls back each time; 3) a break below the intervening lows confirms.", "psy": "Three failures to break through show heavy selling at that level.", "use": "Equivalent to the Western triple top. A bearish candle pattern on the third mountain (e.g., Shooting Star, Evening Star) strengthens the signal."},
  "three-rivers": {"s": "Three drops to the same low, each one held — like three rivers of equal depth.", "rec": "1) Price falls three times to roughly the same low; 2) it bounces each time; 3) a break above the intervening highs confirms.", "psy": "Three failures to break lower show solid buying at that level.", "use": "Equivalent to the Western triple bottom."},
  "uptrend": {"s": "Higher highs and higher lows.", "rec": "A series of higher highs and higher lows. Connecting two or more lows gives an uptrend line.", "psy": "On every pullback, buyers are willing to pay higher prices; demand keeps outpacing supply.", "use": "The first step in reading any candle pattern is the trend: bullish reversals need a prior decline, bearish reversals a prior rally. In an uptrend, bullish patterns (e.g., a Hammer on a pullback to the trend line) have a higher success rate."},
  "downtrend": {"s": "Lower highs and lower lows.", "rec": "A series of lower highs and lower lows. Connecting two or more highs gives a downtrend line.", "psy": "On every bounce, sellers are willing to sell at lower prices.", "use": "Don't rush to bottom-fish in a downtrend. A bearish pattern (e.g., Shooting Star, Dark Cloud Cover) on a bounce to the downtrend line is a place to short or reduce with the trend."},
  "sideways": {"s": "Price swings between an upper and lower boundary with no direction.", "rec": "Roughly equal highs and roughly equal lows; price oscillates within a horizontal channel.", "psy": "Bulls and bears are balanced; the market is waiting for new information.", "use": "Candle patterns in the middle of the range mean little (e.g., a Doji mid-range). Only bearish patterns at the top or bullish patterns at the bottom deserve attention. After a valid breakout, the old top/bottom switches roles."},
  "support-resistance": {"s": "Support = where declines tend to stop; resistance = where rallies tend to stall.", "rec": "Support is where price has repeatedly stopped falling (concentrated demand); resistance is where it has repeatedly stalled and turned down (concentrated supply).", "psy": "People remember past prices: those who bought at support are willing to buy again, and those trapped at resistance want to sell to break even.", "use": "Nison's key point: candle pattern + support/resistance = high probability. A Shooting Star at resistance matters far more than one halfway up a move."},
  "trendline-break": {"s": "A close below the uptrend line suggests the uptrend may be over.", "rec": "In an uptrend, a close clearly below the trend line connecting the lows (in a downtrend, a close above the downtrend line).", "psy": "Buyers are no longer willing to step in at higher lows; the trend structure is broken.", "use": "A trend line break doesn't always mean an immediate reversal; price may move sideways first. A Bearish Engulfing, Dark Cloud Cover or similar pattern at the break strengthens the signal."},
  "polarity": {"s": "Broken resistance becomes new support (and vice versa).", "rec": "Once a price level is decisively broken, its role reverses: resistance becomes support, support becomes resistance.", "psy": "Those who sold at resistance regret it after the breakout and are willing to buy back when price returns to that level.", "use": "A principle Nison covers in detail. A Hammer, Bullish Engulfing or similar pattern on a pullback to old resistance (new support) is a good entry."},
  "retracement": {"s": "After a big move, pullbacks often stop near 38%, 50% or 62% of the move.", "rec": "Measure the start and end of a move and calculate the 38.2%, 50% and 61.8% retracement levels.", "psy": "A 50% retracement, giving back half the move, is the most common psychological level, watched by Eastern and Western traders alike.", "use": "A bullish candle pattern (Hammer, Morning Star, etc.) at a retracement level is a point to add or enter."},
  "golden-cross": {"s": "A short-term moving average crosses above a long-term one.", "rec": "A short-term moving average (e.g., 5-day) crosses above a longer one (e.g., 10- or 20-day).", "psy": "The recent average cost is above the longer-term average cost; buyers are gaining the upper hand.", "use": "Moving averages lag, so they suit confirming trends rather than catching tops and bottoms. Nison suggests candle patterns near a moving average (e.g., a Hammer on a pullback to it) are more reliable."},
  "death-cross": {"s": "A short-term moving average crosses below a long-term one.", "rec": "A short-term moving average crosses below a longer-term one.", "psy": "The recent average cost is below the longer-term one; sellers are gaining the upper hand.", "use": "Confirms a downtrend; a bearish candle pattern on a bounce up to the moving average (from below) is a point to reduce. In sideways markets, crossovers often fail."},
  "rsi": {"s": "Price makes a new high but RSI doesn't — the rally is losing strength.", "rec": "RSI ranges from 0 to 100: above 70 is overbought, below 30 oversold. Price making a new high while RSI falls is bearish divergence; price making a new low while RSI rises is bullish divergence.", "psy": "Price is still rising, but the force behind the rally is fading.", "use": "Divergence alone isn't a sell signal, but with a candle pattern such as an Evening Star or Bearish Engulfing, reliability rises sharply."},
  "stochastic": {"s": "Shows where the close sits within the recent high-low range: >80 is hot, <20 is cold.", "rec": "%K = (Close − N-day low) / (N-day high − N-day low) × 100; %D is a moving average of %K. Above 80 is overbought, below 20 oversold.", "psy": "In rallies, closes tend to be near the top of the range; in declines, near the bottom.", "use": "Works best in sideways markets; in strong trends it can stay overbought/oversold for long periods. Use with candle patterns."},
  "macd": {"s": "Fast average minus slow average; watch the line crossovers and the histogram.", "rec": "MACD line = 12-day EMA − 26-day EMA; signal line = 9-day EMA of MACD; histogram = the difference between the two. (The chart uses shorter settings for demonstration.)", "psy": "Measures trend momentum: longer bars = strengthening momentum, shorter bars = weakening momentum.", "use": "MACD crossing above the signal line is bullish, crossing below is bearish. Use it to confirm candle patterns, e.g., an Evening Star + a MACD bearish crossover."},
  "volume": {"s": "A breakout on rising volume = real; on falling volume = possibly false.", "rec": "Check whether volume on key candles (breakouts, reversals) is clearly above average.", "psy": "Volume represents the money involved. Price moves backed by heavy participation are more credible.", "use": "Nison suggests patterns such as a Bullish Engulfing or Hammer are more reliable on higher volume; beware new highs on shrinking volume."},
  "double-top": {"s": "Two failed attempts at the same high, shaped like the letter M.", "rec": "Two roughly equal highs with a trough between them (the neckline). A close below the neckline confirms.", "psy": "The second rally fails to break through; sellers take control.", "use": "A bearish candle pattern on the second top (Tweezers Top, Shooting Star, etc.) gives early warning."},
  "double-bottom": {"s": "Two drops to the same low, both held, shaped like the letter W.", "rec": "Two roughly equal lows with a peak between them (the neckline). A close above the neckline confirms.", "psy": "The second decline fails to make a new low; buyers take control.", "use": "A Hammer, Bullish Engulfing or similar on the second bottom is a chance to enter early."},
  "channel": {"s": "Draw a line parallel to the uptrend line above price; price moves between the two lines.", "rec": "An uptrend line (connecting lows) + a parallel channel line through the highs.", "psy": "The trend advances in a steady rhythm; the upper channel line is a short-term profit-taking zone.", "use": "A bearish candle pattern at the upper line is a chance to trim short-term; a bullish pattern at the lower line is a point to add."},
  "box-breakout": {"s": "After breaking out of a box, price often travels another box height.", "rec": "After consolidating in a box, price closes above the top. Target ≈ breakout point + box height.", "psy": "The longer the consolidation, the stronger the momentum after the breakout.", "use": "Nison covers box breakouts in his chapter on measured targets. A pullback that holds the old box top (change of polarity) is a second entry."},
  "window-support": {"s": "On a pullback after a gap up, the rally is intact as long as price doesn't close below the window.", "rec": "After a rising window (gap up), pullbacks into the window area find support.", "psy": "A Japanese saying: \"The market will return to the window.\" The window (gap) is the bulls' line of defense.", "use": "Nison: support fails only on a close below the entire window (its bottom edge)."},
  "elliott": {"s": "A rally unfolds in 5 waves (1-3-5 up, 2-4 down), followed by a 3-wave A-B-C correction.", "rec": "Five-wave impulse: waves 1, 3, 5 rise and waves 2, 4 retrace; wave 3 is usually the longest; then an A-B-C three-wave correction.", "psy": "Crowd sentiment alternates rhythmically between optimism and pessimism.", "use": "Wave counting is highly subjective. Look for bearish candle patterns at the end of wave 5 as supporting confirmation."},
  "convergence": {"s": "Reliability is highest when several signals line up at the same spot.", "rec": "E.g., a Morning Star at prior support + a 50% retracement + oversold RSI.", "psy": "The more independent methods point to the same conclusion, the less likely it is chance.", "use": "The core idea of Nison's whole book: candle patterns are only a tool and should be combined with trend, support/resistance and indicators, never read in isolation."}
};
